import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 3

def design(feats):
    # Identify potential drivers using t-test and correlation filtering
    candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
        if abs(t_stat) > 1.5 and p_val < 0.05:
            candidates.append((abs(t_stat), fid))

    candidates.sort(reverse=True)
    drivers = [fid for _, fid in candidates[:MAX_DRIVERS]]

    # Filter out near-duplicates based on correlations
    filtered_drivers = []
    used = set()
    for fid in drivers:
        if fid in used:
            continue
        correlated = False
        for other_fid in filtered_drivers:
            col_a = feats.column(fid)
            col_b = feats.column(other_fid)
            corr = np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0, 1]
            if abs(corr) >= 0.6:
                correlated = True
                break
        if not correlated:
            filtered_drivers.append(fid)
            used.add(fid)

    # Check for product terms between top drivers
    products = []
    for i, a in enumerate(filtered_drivers):
        for b in filtered_drivers[i+1:]:
            col_a = feats.column(a)
            col_b = feats.column(b)
            # Check if interaction term would be useful
            if abs(np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0, 1]) < 0.6:
                products.append((a, b))

    # Build final design
    return Design(
        drivers=tuple(filtered_drivers),
        columns=filtered_drivers,
        products=tuple(products),
        loadings={}
    )

